use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut min = None;
    let mut max = None;

    for num in arr {
        let num_value = num.as_i64().unwrap();
        if min.is_none() || num_value < min.unwrap() {
            min = Some(num_value);
        }
        if max.is_none() || num_value > max.unwrap() {
            max = Some(num_value);
        }
    }

    if min.is_none() || max.is_none() {
        Value::Null
    } else {
        Value::Array(vec![Value::Number(min.unwrap()), Value::Number(max.unwrap())])
    }
}
